            chain=label[0] if label else a.chain or ' '
            s+='ATOM  %5d %4s %4s%c%4d    '%(i%100000,name,a.resname[:4],chain,a.resnr%10000)+''.join('%8.3f'%(10*v) for v in a.x)+'%6.2f%6.2f          %2s\n'%(a.occ,a.beta,a.element[:2])
