def length(v):return math.sqrt(sum(x*x for x in v))
def box_info(box):
    lens=[length(row) for row in box];angs=[]
    for i,j in [(1,2),(0,2),(0,1)]:
        den=lens[i]*lens[j];angs.append(math.degrees(math.acos(max(-1,min(1,sum(a*b for a,b in zip(box[i],box[j]))/den)))) if den else 90.)
    vol=box[0][0]*(box[1][1]*box[2][2]-box[1][2]*box[2][1])-box[0][1]*(box[1][0]*box[2][2]-box[1][2]*box[2][0])+box[0][2]*(box[1][0]*box[2][1]-box[1][1]*box[2][0])
    return lens,angs,vol

def make_box(sizes,angles=(90,90,90),boxtype='triclinic'):
    x,y,z=sizes
    if boxtype=='cubic':return [[x,0,0],[0,x,0],[0,0,x]]
    if boxtype=='dodecahedron':return [[x,0,0],[0,x,0],[f32(.5*x),f32(.5*x),f32(math.sqrt(.5)*x)]]
    if boxtype=='octahedron':return [[x,0,0],[f32(x/3),f32(x*math.sqrt(8/9)),0],[f32(-x/3),f32(x*math.sqrt(2/9)),f32(x*math.sqrt(2/3))]]
    a,b,c=[math.radians(x) for x in angles]
    ca,cb,cc=[0 if abs(v)<1e-12 else v for v in [math.cos(a),math.cos(b),math.cos(c)]]
    b00=x;b10=y*cc;b11=y*math.sin(c);b20=z*cb;b21=z*(ca-cb*cc)/math.sin(c) if math.sin(c) else 0.;b22=math.sqrt(max(0,z*z-b20*b20-b21*b21))
    return [[f32(b00),0,0],[f32(b10),f32(b11),0],[f32(b20),f32(b21),f32(b22)]]

def format_structure(fr,path,vel=None,label=None):
    ext=os.path.splitext(path)[1].lower();atoms=fr.atoms
    if ext in ['.pdb','.brk','.ent','.pqr']:
        s='TITLE     '+(fr.title or '')+'\nREMARK    THIS IS A SIMULATION BOX\n'
        lens,angles,vol=box_info(fr.box)
        if any(lens):s+='CRYST1'+''.join('%9.3f'%(10*x) for x in lens)+''.join('%7.2f'%x for x in angles)+' P 1           1\n'
        s+='MODEL        1\n'
        for i,a in enumerate(atoms,1):
            name=a.name[:4];name=(' '+name).ljust(4) if len(name)<4 else name
            chain=label[0] if label else a.chain or ' '
            s+='ATOM  %5d %4s %4s%c%4d    '%(i%100000,name,a.resname[:4],chain,a.resnr%10000)+''.join('%8.3f'%(10*v) for v in a.x)+'%6.2f%6.2f          %2s\n'%(a.occ,a.beta,a.element[:2])
        s+='TER\nENDMDL\n';return s
    if ext=='.g96':
        s='TITLE\n'+fr.title+'\nEND\nPOSITION\n'
        for i,a in enumerate(atoms,1):s+='%5d %-5s %-5s %6d'%(a.resnr%100000,a.resname[:5],a.name[:5],i%1000000)+''.join('%15.9f'%v for v in a.x)+'\n'
        s+='END\n'
        if vel or any(a.v is not None for a in atoms):
            s+='VELOCITY\n'
            for i,a in enumerate(atoms,1):s+='%5d %-5s %-5s %6d'%(a.resnr%100000,a.resname[:5],a.name[:5],i%1000000)+''.join('%15.9f'%v for v in (a.v or [0,0,0]))+'\n'
            s+='END\n'
        s+='BOX\n'+''.join('%15.9f'%fr.box[k][k] for k in range(3))+'\nEND\n';return s
    s=fr.title+'\n%5d\n'%len(atoms)
    for i,a in enumerate(atoms,1):
        s+='%5d%-5s%5s%5d'%(a.resnr%100000,a.resname[:5],a.name[:5],i%100000)+''.join('%8.3f'%x for x in a.x)
        if vel is not False and (vel or a.v is not None):s+=''.join('%8.4f'%x for x in (a.v or [0,0,0]))
        s+='\n'
    b=[fr.box[i][i] for i in range(3)]
    if any(fr.box[j][k] for j in range(3) for k in range(3) if j!=k):b+=[fr.box[j][k] for j,k in [(0,1),(0,2),(1,0),(1,2),(2,0),(2,1)]]
    s+=''.join('%10.5f'%x for x in b)+'\n';return s

def genconf(app):
    o=app.opts;nb=[int(x) for x in o['nbox']]
    if any(x<=0 for x in nb):app.fatal('Number of boxes (-nbox) should be larger than zero','gmxpreprocess/genconf.cpp',187)
    fr=read_frames(app,o['f'])[0];new=copy.deepcopy(fr);new.atoms=[];idx=0
    nres=max((a.resindex for a in fr.atoms),default=-1)+1
    for ix in range(nb[0]):
        for iy in range(nb[1]):
            for iz in range(nb[2]):
                offset=[ix,iy,iz];trans=[sum(fr.box[k][d]*offset[k] for k in range(3))+offset[d]*o['dist'][d] for d in range(3)]
                for a in fr.atoms:
                    a=copy.deepcopy(a);a.x=[f32(v+tr) for v,tr in zip(a.x,trans)];a.nr=len(new.atoms)+1
                    if o['renumber']:a.resnr=a.resindex+1+idx*nres
                    if a.v is None:a.v=[0.,0.,0.]
                    new.atoms.append(a)
                idx+=1
    for k in range(3):
        for j in range(3):new.box[k][j]=f32((fr.box[k][j]+(o['dist'][k] if k==j else 0))*nb[k])
    app.write(o['o'],format_structure(new,o['o'],vel=True))

def editconf(app):
    o=app.opts;p=app.present
    app.out('Note that major changes are planned in future for editconf, to improve usability and utility.')
    app.library('residuetypes.dat')
    fr=read_frames(app,o['f'])[0];atoms=fr.atoms;n=len(atoms);l,an,vol=box_info(fr.box)
    app.out('Read %d atoms'%n);app.out('Volume: %s nm^3, corresponds to roughly %d electrons'%(g(vol),int(vol*450)))
    if not any(a.v is not None for a in atoms):app.out('No velocities found')
    if any(k in p for k in ['density','princ','align','grasp','mead']):app.library('atommass.dat')
    if not n:return
    oldcoords=[a.x[:] for a in atoms]
    def bounds():
        sizes=[f32(max(a.x[k] for a in atoms)-min(a.x[k] for a in atoms)) for k in range(3)]
        center=[f32(sum(a.x[k] for a in atoms)/n) for k in range(3)]
        return sizes,center
    sizes,center=bounds();changed=any(k in p for k in ['box','d','angles','scale']);bcenter=o['c'] or ('center' in p) or (('box' in p or 'd' in p) and ('c' not in p or o['c']))
    report=bcenter or any(k in p for k in ['scale','d','rotate','princ','align'])
    def vline(label,v,units=' (nm)',fmt='%7.3f'):app.out(label+''.join(fmt%x for x in v)+units)
    def bline(prefix):
        l,a,v=box_info(fr.box);vline(prefix+'box vectors :',l);vline(prefix+'box angles  :',a,' (degrees)','%7.2f');app.out(prefix+'box volume  :%7.2f               (nm^3)'%v)
    if report:
        vline('    system size :',sizes)
        if 'd' in p and o['bt']!='triclinic':
            diameter=max((length([a.x[k]-b.x[k] for k in range(3)]) for a in atoms for b in atoms),default=0.);app.out('    diameter    :%7.3f               (nm)'%diameter)
        vline('    center      :',center);bline('    ')
    if 'scale' in p:
        for a in atoms:a.x=[f32(x*s) for x,s in zip(a.x,o['scale'])]
        fr.box=[[f32(x*o['scale'][j]) for j,x in enumerate(row)] for row in fr.box]
    if 'rotate' in p:
        app.out('Rotating %s, %s, %s degrees around the X, Y and Z axis respectively'%tuple(g(x) for x in o['rotate']))
        for a in atoms:
            for attr in ['x','v']:
                v=getattr(a,attr)
                if v is None:continue
                for axis in range(3):
                    angle=math.radians(o['rotate'][axis]);c=math.cos(angle);s=math.sin(angle);j=(axis+1)%3;k=(axis+2)%3
                    x,y=v[j],v[k];v[j]=f32(c*x-s*y);v[k]=f32(s*x+c*y)
    if 'box' in p:fr.box=make_box(o['box'],o['angles'],o['bt'])
    if 'd' in p:
        sizes,center=bounds()
        if o['bt']=='triclinic':sz=[f32(x+2*o['d']) for x in sizes]
        else:
            diameter=max((length([a.x[k]-b.x[k] for k in range(3)]) for a in atoms for b in atoms),default=0.)
            sz=[f32(diameter+2*o['d'])]*3
        fr.box=make_box(sz,boxtype=o['bt'])
    if bcenter:
        _,center=bounds()
        target=o['center'] if 'center' in p else [f32(.5*sum(fr.box[k][j] for k in range(3))) for j in range(3)]
        shift=[f32(target[j]-center[j]) for j in range(3)];vline('    shift       :',shift)
        for a in atoms:a.x=[f32(x+s) for x,s in zip(a.x,shift)]
    if 'scale' in p or 'rotate' in p:
        sizes,center=bounds();vline('new system size :',sizes,'')
    if report:
        _,center=bounds();vline('new center      :',center)
    if changed:bline('new ')
    if 'translate' in p:
        app.out('Translating %d atoms (out of %d) by %s %s %s nm'%(n,n,*[g(x) for x in o['translate']]))
