def read_binary(app,path,ext):
    data=open(path,'rb').read();frames=[];pos=0
    def unpack(fmt):
        nonlocal pos
        size=struct.calcsize('>'+fmt)
        r=struct.unpack_from('>'+fmt,data,pos);pos+=size;return r
    def num(fmt):return unpack(fmt)[0]
    try:
        while pos+4<=len(data):
            magic=num('i');fr=Frame()
            if ext=='.xtc':
                if magic!=1995:break
                natoms,fr.step=unpack('ii');fr.time=num('f');fr.hasstep=True;fr.hastime=True;fr.box=[list(unpack('fff')) for _ in range(3)]
                n=num('i')
                if n<=9:xs=[list(unpack('fff')) for _ in range(n)]
                else:break
                fr.atoms=[Atom(1,'','',i+1,x) for i,x in enumerate(xs)]
            else:
                if magic!=1993:break
                slen=num('i');slen=num('i');pos+=(slen+3)//4*4
                sizes=unpack('10i');natoms,fr.step,nre=unpack('iii');fr.hasstep=True;fr.hastime=True
                precision=4
                for s,c in [(sizes[2],9),(sizes[7],3*natoms),(sizes[8],3*natoms)]:
                    if s and c:precision=s//c;break
                real='d' if precision==8 else 'f';fr.time,lam=unpack(real*2)
                box=[];xs=[];vs=[]
                for b,size in enumerate(sizes):
                    if not size:continue
                    if b==2:fr.box=[list(unpack(real*3)) for _ in range(3)]
                    elif b in [7,8,9]:
                        values=[list(unpack(real*3)) for _ in range(natoms)]
                        if b==7:xs=values
                        if b==8:vs=values
                    else:pos+=size
                fr.atoms=[Atom(1,'','',i+1,x,vs[i] if vs else None) for i,x in enumerate(xs)]
            frames.append(fr)
    except (struct.error,ValueError):pass
    return frames
