"""Trajectory and index consistency reporting."""
import os,math,re
from common import *
from structures import *
from indexing import read_index

def start_trajectory(app,path,frames):
    ext=os.path.splitext(path)[1]
    if ext=='.gro' and frames:app.err("Reading frames from gro file '%s', %d atoms."%(frames[0].title,len(frames[0].atoms)))
    elif ext=='.trr':app.err('trr version: GMX_trn_file (single precision)')
    elif ext in ['.pdb','.brk','.ent'] and frames:app.err("Reading frames from pdb file '%s', %d atoms."%(frames[0].title,len(frames[0].atoms)))

def progress(app,i,t,last=False):
    app.err(('\rLast frame     ' if last else '\rReading frame  ')+'%6d time %8.3f   '%(i,t),end='\n' if last else '')

def check(app):
    o=app.opts;p=app.present
    if 'n' in p:
        groups=read_index(app,o['n'])
        app.out('Contents of index file '+o['n']+'\n'+'-'*50+'\nNr.   Group               #Entries   First    Last')
        for i,(name,vals) in enumerate(groups):
            if vals:app.out('%4d  %-20s%8d%8d%8d'%(i,name,len(vals),vals[0],vals[-1]))
    if 'c' in p:
        app.err('Checking coordinate file '+o['c']);app.library('residuetypes.dat');app.library('atommass.dat');app.library('vdwradii.dat')
    if 's1' in p:read_frames(app,o['s1'])
    if 'f' not in p:return
    path=o['f'];frames=read_frames(app,path)
    if 'f2' in p:
        other=read_frames(app,o['f2']);app.err('Comparing trajectory files %s and %s'%(path,o['f2']))
        start_trajectory(app,path,frames)
        if frames:progress(app,0,frames[0].time)
        start_trajectory(app,o['f2'],other)
        if other:progress(app,0,other[0].time)
        for i in range(1,min(len(frames),len(other))):progress(app,i,frames[i].time);progress(app,i,other[i].time)
        if frames:progress(app,len(frames)-1,frames[-1].time,True)
        if other:progress(app,len(other)-1,other[-1].time,True)
        app.out('\n\nBoth files read correctly')
        return
    app.out('Checking file '+path);start_trajectory(app,path,frames)
    if not frames:return
    n=len(frames);dt=(frames[-1].time-frames[0].time)/(n-1) if n>1 else 0
    for i,fr in enumerate(frames):
        progress(app,i,fr.time)
        if i==0:
            app.err('\n# Atoms  %d'%len(fr.atoms))
            if os.path.splitext(path)[1] in ['.gro','.xtc']:app.err('Precision %s (nm)'%g(1/fr.precision))
    progress(app,n-1,frames[-1].time,True)
    app.err('\n\nItem        #frames Timestep (ps)')
    counts=[sum(f.hasstep for f in frames),sum(f.hastime for f in frames),n if path.endswith('.trr') else 0,n,sum(any(a.v is not None for a in f.atoms) for f in frames),0,sum(any(v for row in f.box for v in row) for f in frames)]
    for key,count in zip(['Step','Time','Lambda','Coords','Velocities','Forces','Box'],counts):
        app.err('%-12s%6d'%(key,count)+('    '+g(dt) if count>1 else ''))

def dump_trajectory(app,path):
    frames=read_frames(app,path)
    if path.endswith('.trr'):app.err('trr version: GMX_trn_file (single precision)')
    for i,fr in enumerate(frames):
        n=len(fr.atoms);app.out('%s frame %d:'%(path,i));app.out('   natoms=%10d  step=%10d  time=%13.7e  lambda=%10g'%(n,fr.step,fr.time,0))
        def matrix(name,vs):
            app.out('   %s (%dx3):'%(name,len(vs)))
            for j,v in enumerate(vs):app.out('      %s[%5d]={%12.5e, %12.5e, %12.5e}'%(name,j,*v))
        matrix('box',fr.box);matrix('x',[a.x for a in fr.atoms])
        if any(a.v is not None for a in fr.atoms):matrix('v',[a.v or [0,0,0] for a in fr.atoms])
