                if name.isdigit():return set(self.groups[int(name)][1]) if int(name)<len(self.groups) else set()
                return set(next((ids for nm,ids in self.groups if nm.lower()==name.lower()),[]))
            m=re.match(r'(atomnr|resnr|resid|resindex|molindex)\s+(.+)',s)
            if m:
                key,part=m.groups();values=set();tokens=part.split();i=0
                while i<len(tokens):
