    tokens=re.findall(r'[A-Za-z_][\w-]*',stripped)
    valid={'all','none','atomnr','resnr','resid','resindex','resname','name','atomname','group','not','com','cog','x','y','z','within','same','mass','charge','molindex','chain'}
